import React, { useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import type { CatalogCategory, CatalogItem, Dashboard, DateRange, Publication, PushPreview, RuntimeConfig, SyncPreview, SyncStatus } from "../shared/contracts";
import { isPublishableItem, sanitizePublication, searchableCatalogItem } from "../shared/catalog";
import { CatalogEditorModal } from "./CatalogEditorModal";
import { CategoryManagerModal } from "./CategoryManagerModal";
import "./styles.css";

type Page = "dashboard" | "orders" | "catalog" | "menu" | "operations" | "expenses" | "reports" | "inbox" | "sync" | "settings";
const money = (value: number) => new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(value || 0);
const indiaDateTime = new Intl.DateTimeFormat("en-IN", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", second: "2-digit", timeZone: "Asia/Kolkata" });
function displayValue(key:string,value:unknown){if(value==null)return "-";if(/(?:^|_)(?:started|completed|created|updated|published|received)_at$/.test(key)&&typeof value==="string"){const date=new Date(value);if(!Number.isNaN(date.getTime()))return `${indiaDateTime.format(date)} IST`;}return String(value);}
const today = () => new Date().toISOString().slice(0, 10);
const monthRange = (): DateRange => {
  const date = new Date();
  return { from: `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-01`, to: today() };
};
const nav: [Page, string, string][] = [
  ["dashboard", "Overview", "OV"], ["orders", "Orders", "OR"],
  ["catalog", "Catalog", "CA"], ["menu", "One-day menu", "MN"], ["operations", "Operations", "OP"],
  ["expenses", "Expenses", "EX"], ["reports", "Reports", "RP"],
];
const pageTitles:Record<Page,string>={dashboard:"Overview",orders:"Orders",catalog:"Catalog",menu:"One-day menu",operations:"Operations",expenses:"Expenses",reports:"Reports",inbox:"WhatsApp inbox",sync:"Sync Centre",settings:"Settings"};

function UtilityIcon({name}:{name:"settings"|"sync"|"whatsapp"}){const paths={settings:<><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-1.6v-.2h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z"/></>,sync:<><path d="M20 7h-6V1"/><path d="m20 1-6 6a8 8 0 1 0 2.3 8.7"/></>,whatsapp:<><path d="M20 11.5a8 8 0 0 1-11.8 7L3 20l1.5-5.1A8 8 0 1 1 20 11.5Z"/><path d="M8.5 8.2c.5 3 2.3 4.8 5.3 5.3"/></>};return <svg viewBox="0 0 24 24" aria-hidden="true">{paths[name]}</svg>;}

function App() {
  const [page, setPage] = useState<Page>("dashboard");
  const [range, setRange] = useState(monthRange);
  const [notice, setNotice] = useState("");
  const [dataVersion, setDataVersion] = useState(0);
  const [startupLoading, setStartupLoading] = useState(true);
  useEffect(() => window.admin.sync.onStartupPullComplete(() => setDataVersion((value) => value + 1)), []);
  useEffect(() => {const started=Date.now();const finish=()=>setTimeout(()=>setStartupLoading(false),Math.max(0,700-(Date.now()-started)));const unsubscribe=window.admin.sync.onStartupPullSettled(finish);const safety=setTimeout(()=>setStartupLoading(false),8000);return()=>{unsubscribe();clearTimeout(safety);};}, []);
  const title = pageTitles[page];
  return <>{startupLoading&&<StartupLoader/>}<div className="app-shell">
    <aside><div className="brand"><b>G</b><div><strong>Gruhswad</strong><span>Kitchen admin</span></div></div>
      <div className="utility-nav" aria-label="Administration shortcuts"><button className={page==="settings"?"active":""} title="Settings" aria-label="Settings" onClick={()=>setPage("settings")}><UtilityIcon name="settings"/></button><button className={page==="sync"?"active":""} title="Sync Centre" aria-label="Sync Centre" onClick={()=>setPage("sync")}><UtilityIcon name="sync"/></button><button className="disabled" title="WhatsApp Inbox - coming soon" aria-label="WhatsApp Inbox is temporarily disabled" aria-disabled="true" onClick={()=>setNotice("WhatsApp Inbox is temporarily disabled. We can enable it when required.")}><UtilityIcon name="whatsapp"/><span>Coming soon</span></button></div>
      <nav>{nav.map(([id, label, icon]) => <button className={page === id ? "active" : ""} onClick={() => setPage(id)} key={id}><i>{icon}</i>{label}</button>)}</nav>
      <div className="side-note"><span>Local-first</span><p>Your operational data stays on this computer.</p></div>
    </aside>
    <main><header><div><small>HOME KITCHEN OPERATIONS</small><h1>{title}</h1></div>{!(["menu", "settings", "inbox", "catalog", "operations", "orders", "sync"] as Page[]).includes(page) && <DateFilter range={range} setRange={setRange} />}</header>
      {notice && <div className="notice" onClick={() => setNotice("")}>{notice}</div>}
      <React.Fragment key={`${page}-${dataVersion}`}>
        {page === "dashboard" && <DashboardPage range={range} />}
        {page === "orders" && <CloudOrdersPage notify={setNotice} />}
        {page === "catalog" && <CatalogPage notify={setNotice} />}
        {page === "expenses" && <ExpensesPage range={range} notify={setNotice} />}
        {page === "reports" && <ReportsPage range={range} notify={setNotice} />}
        {page === "menu" && <MenuPage notify={setNotice} />}
        {page === "operations" && <OperationsPage notify={setNotice} />}
        {page === "inbox" && <Panel title="WhatsApp Inbox"><Empty text="WhatsApp Inbox is temporarily disabled." /></Panel>}
        {page === "sync" && <SyncPage notify={setNotice} />}
        {page === "settings" && <SettingsPage notify={setNotice} />}
      </React.Fragment>
    </main>
  </div></>;
}

function StartupLoader(){return <div className="startup-loader" role="status" aria-live="polite"><div className="loader-mark"><span>G</span><i></i><i></i><i></i></div><strong>Gruhswad</strong><p>Preparing your kitchen dashboard</p><div className="loader-steam"><b></b><b></b><b></b></div></div>;}

function DateFilter({ range, setRange }: { range: DateRange; setRange: (value: DateRange) => void }) {
  return <div className="date-filter"><label>From<input type="date" value={range.from} onChange={(event) => setRange({ ...range, from: event.target.value })} /></label><label>To<input type="date" value={range.to} onChange={(event) => setRange({ ...range, to: event.target.value })} /></label></div>;
}

function DashboardPage({ range }: { range: DateRange }) {
  const [data, setData] = useState<Dashboard | null>(null);
  useEffect(() => { window.admin.dashboard(range).then(setData); }, [range]);
  if (!data) return <Empty text="Loading dashboard..." />;
  return <><section className="metric-grid"><Metric label="Completed revenue" value={money(data.revenue)} tone="green" /><Metric label="Expenses" value={money(data.expenses)} tone="red" /><Metric label="Profit / loss" value={money(data.profit)} tone={data.profit >= 0 ? "gold" : "red"} /><Metric label="Orders" value={String(data.orderCount)} tone="brown" /><Metric label="Open order value" value={money(data.outstanding)} tone="red" /><Metric label="Average order" value={money(data.averageOrder)} tone="green" /></section>
    <section className="split"><Panel title="Recent orders"><p className="muted">Orders placed during the selected date range, including orders with a later pickup date.</p><DataTable rows={data.recentOrders} columns={[["customer_name", "Customer"], ["created_at", "Placed at"], ["service_date", "Pickup date"], ["status", "Status"], ["total", "Total"]]} moneyKeys={["total"]} /></Panel>
      <Panel title="Expenses by category">{data.expenseByCategory.length ? <div className="bars">{data.expenseByCategory.map((row) => <div key={row.category}><span>{row.category}</span><b style={{ width: `${Math.max(8, row.total / Math.max(...data.expenseByCategory.map((item) => item.total)) * 100)}%` }} /><strong>{money(row.total)}</strong></div>)}</div> : <Empty text="No expenses in this period." />}</Panel>
    </section></>;
}
function Metric({ label, value, tone }: { label: string; value: string; tone: string }) { return <article className={`metric ${tone}`}><span>{label}</span><strong>{value}</strong></article>; }

function OrdersPage({ range, notify }: { range: DateRange; notify: (message: string) => void }) {
  const [rows, setRows] = useState<any[]>([]); const [catalog, setCatalog] = useState<any>({ items: [] }); const [open, setOpen] = useState(false);
  const load = () => window.admin.orders.list(range).then(setRows);
  useEffect(() => { load(); window.admin.menu.catalog().then(setCatalog); }, [range]);
  async function status(id: string, value: any) { await window.admin.orders.updateStatus(id, value); load(); notify("Order status updated."); }
  async function paid(row: any) { const amount = Math.max(0, row.total - row.paid); if (!amount) return; await window.admin.orders.addPayment({ orderId: row.id, amount, receivedAt: new Date().toISOString(), method: "UPI", status: "received" }); load(); notify("Payment recorded."); }
  return <Panel title="Order history" action={<button className="primary" onClick={() => setOpen(true)}>New order</button>}>
    {open && <OrderForm items={catalog.items} close={() => setOpen(false)} saved={() => { setOpen(false); load(); notify("Order saved."); }} />}
    {rows.length ? <div className="order-list">{rows.map((row) => <article key={row.id}><div><strong>{row.customer_name}</strong><span>{row.service_date} / {row.phone}</span></div><b>{money(row.total)}</b><select value={row.status} onChange={(event) => status(row.id, event.target.value)}>{["draft", "confirmed", "preparing", "ready", "completed", "cancelled"].map((value) => <option key={value}>{value}</option>)}</select><button disabled={row.payment_status === "paid"} onClick={() => paid(row)}>{row.payment_status === "paid" ? "Paid" : "Mark paid"}</button></article>)}</div> : <Empty text="No orders found for this period." />}
  </Panel>;
}

function OrderForm({ items, close, saved }: { items: any[]; close: () => void; saved: () => void }) {
  const [name, setName] = useState(""); const [phone, setPhone] = useState(""); const [date, setDate] = useState(today()); const [selected, setSelected] = useState("");
  const item = items.find((value) => value.id === selected);
  async function submit(event: React.FormEvent) { event.preventDefault(); if (!item) return; await window.admin.orders.save({ customerName: name, phone, serviceDate: date, fulfilment: "pickup", address: "", notes: "", source: "manual", status: "draft", lines: [{ menuItemId: item.id, name: item.name, quantity: 1, unitPrice: item.price }] }); saved(); }
  return <form className="inline-form" onSubmit={submit}><h3>Record an order</h3><label>Customer<input required value={name} onChange={(event) => setName(event.target.value)} /></label><label>Phone<input required value={phone} onChange={(event) => setPhone(event.target.value)} /></label><label>Service date<input type="date" required value={date} onChange={(event) => setDate(event.target.value)} /></label><label>Dish<select required value={selected} onChange={(event) => setSelected(event.target.value)}><option value="">Choose a dish</option>{items.filter((value) => value.available).map((value) => <option value={value.id} key={value.id}>{value.name} / {money(value.price)}</option>)}</select></label><div><button type="button" onClick={close}>Cancel</button><button className="primary">Save order</button></div></form>;
}

function ExpensesPage({ range, notify }: { range: DateRange; notify: (message: string) => void }) {
  const [rows, setRows] = useState<any[]>([]); const [form, setForm] = useState({ date: today(), category: "Ingredients", description: "", amount: "", paymentMethod: "UPI", notes: "" });
  const load = () => window.admin.expenses.list(range).then(setRows); useEffect(() => { load(); }, [range]);
  async function submit(event: React.FormEvent) { event.preventDefault(); await window.admin.expenses.save({ ...form, amount: Number(form.amount) }); setForm({ ...form, description: "", amount: "", notes: "" }); load(); notify("Expense recorded."); }
  return <section className="split wide-left"><Panel title="Monthly expenses"><DataTable rows={rows} columns={[["date", "Date"], ["category", "Category"], ["description", "Description"], ["payment_method", "Paid via"], ["amount", "Amount"]]} moneyKeys={["amount"]} actions={(row) => <button className="danger" onClick={async () => { if (!confirm(`Delete expense: ${row.description}?`)) return; await window.admin.expenses.remove(row.id); await load(); notify("Expense deleted."); }}>Delete</button>} /></Panel><Panel title="Record purchase"><form className="stack-form" onSubmit={submit}>{Object.entries(form).map(([key, value]) => <label key={key}>{key === "paymentMethod" ? "Payment method" : key.replace(/^./, (letter) => letter.toUpperCase())}<input type={key === "date" ? "date" : key === "amount" ? "number" : "text"} required={key !== "notes"} value={value} onChange={(event) => setForm({ ...form, [key]: event.target.value })} /></label>)}<button className="primary">Add expense</button></form></Panel></section>;
}

function ReportsPage({ range, notify }: { range: DateRange; notify: (message: string) => void }) {
  const [data, setData] = useState<Dashboard | null>(null); useEffect(() => { window.admin.dashboard(range).then(setData); }, [range]);
  return <><section className="report-hero"><div><span>Completed-order result</span><strong>{money(data?.profit ?? 0)}</strong><p>Completed revenue {money(data?.revenue ?? 0)} minus local expenses {money(data?.expenses ?? 0)}</p></div></section><section className="metric-grid report-metrics"><Metric label="Completed revenue" value={money(data?.revenue ?? 0)} tone="green"/><Metric label="Local expenses" value={money(data?.expenses ?? 0)} tone="red"/><Metric label="Orders" value={String(data?.orderCount ?? 0)} tone="brown"/></section><Panel title="Export monthly records"><div className="export-grid">{(["orders", "expenses", "summary"] as const).map((kind) => <button key={kind} onClick={async () => { const path = await window.admin.reports.exportCsv(kind, range); if (path) notify(`Saved ${kind} report.`); }}><b>{kind}</b><span>Download CSV -&gt;</span></button>)}</div></Panel></>;
}

function MenuPage({ notify }: { notify: (message: string) => void }) {
  const [catalog, setCatalog] = useState<{categories:CatalogCategory[];items:CatalogItem[]}>({ categories: [], items: [] });
  const [selected, setSelected] = useState<string[]>([]); const [featured, setFeatured] = useState<string | null>(null); const [date, setDate] = useState(today()); const [title, setTitle] = useState("Tomorrow's Fresh Menu"); const [cutoff, setCutoff] = useState("Order before 9:00 PM for next-day delivery"); const [query, setQuery] = useState(""); const [hasSaved,setHasSaved]=useState(false); const [exporting,setExporting]=useState<"compact"|"photo"|null>(null);
  useEffect(() => { Promise.all([window.admin.menu.catalog(), window.admin.menu.getCurrent()]).then(([value,current]) => { setCatalog(value); setHasSaved(Boolean(current)); const safe=sanitizePublication(current,value.categories,value.items); if(safe){setDate(safe.date);setTitle(safe.title);setCutoff(safe.orderCutoff);setSelected(safe.itemIds);setFeatured(safe.featuredItemId);} }); }, []);
  const items=catalog.items.filter((item)=>isPublishableItem(item,catalog.categories)&&searchableCatalogItem(item,query));
  async function publish(){const payload:Publication={date,published:true,title,itemIds:selected,featuredItemId:featured,orderCutoff:cutoff};await window.admin.menu.publish(payload);setHasSaved(true);notify("Menu saved locally. Use Sync Centre to push it to Neon.");}
  async function exportPdf(kind:"compact"|"photo"){setExporting(kind);try{const result=kind==="photo"?await window.admin.menu.exportPhotoPdf():await window.admin.menu.exportPdf();if(result.canceled){notify("One-day menu PDF export was cancelled.");return;}notify(result.warning??`One-day menu PDF saved successfully (${result.pageCount} ${result.pageCount===1?"page":"pages"}).`);}catch(error){notify(`One-day menu PDF export failed: ${error instanceof Error?error.message:String(error)}`);}finally{setExporting(null);}}
  return <section className="menu-builder"><div><Panel title="Build the one-day menu"><div className="publish-fields"><label>Service date<input type="date" value={date} onChange={(event)=>setDate(event.target.value)}/></label><label>Title<input value={title} onChange={(event)=>setTitle(event.target.value)}/></label><label>Cutoff<input value={cutoff} onChange={(event)=>setCutoff(event.target.value)}/></label></div><input className="search" placeholder="Search the master menu" value={query} onChange={(event)=>setQuery(event.target.value)}/><div className="catalog-grid">{items.map((item)=><label className={selected.includes(item.id)?"selected":""} key={item.id}><input type="checkbox" checked={selected.includes(item.id)} onChange={()=>setSelected((current)=>current.includes(item.id)?current.filter((id)=>id!==item.id):[...current,item.id])}/><span><strong>{item.name}</strong><small>{item.portion} / {money(item.price)}</small></span></label>)}</div></Panel></div><aside className="selection-card"><span>{selected.length} selected</span><h2>Tomorrow's menu</h2>{selected.map((id)=>{const item=catalog.items.find((value)=>value.id===id);return <FeaturedSelectionRow key={id} item={item} active={featured===id} toggle={()=>setFeatured(featured===id?null:id)}/>;})}<button className="primary publish" disabled={!selected.length} onClick={()=>publish().catch((error)=>notify(error.message))}>Save menu locally</button><button className="pdf-export-menu" disabled={!hasSaved||Boolean(exporting)} onClick={()=>exportPdf("compact")}>{exporting==="compact"?"Generating PDF...":"Export saved menu PDF"}</button><button className="pdf-export-menu photo" disabled={!hasSaved||Boolean(exporting)} onClick={()=>exportPdf("photo")}>{exporting==="photo"?"Generating photo PDF...":"Export menu PDF with photos"}</button><small>Use the star to choose Today's Special. Both PDF exports use the latest locally saved menu.</small></aside></section>;
}

function FeaturedSelectionRow({item,active,toggle}:{item:CatalogItem|undefined;active:boolean;toggle():void}){const name=item?.name??"Selected item";const action=active?`Clear ${name} as Today's Special`:`Set ${name} as Today's Special`;return <div className={active?"selected-line featured":"selected-line"}><button type="button" className={active?"star on":"star"} aria-label={action} aria-pressed={active} title={action} onClick={toggle}>{"\u2605"}</button><span className="selected-item-name"><strong>{name}</strong>{active&&<small>Today's Special</small>}</span><b>{money(item?.price??0)}</b></div>}

function LegacyMenuPage({ notify }: { notify: (message: string) => void }) {
  const [catalog, setCatalog] = useState<any>({ categories: [], items: [] }); const [selected, setSelected] = useState<string[]>([]); const [featured, setFeatured] = useState<string | null>(null); const [date, setDate] = useState(today()); const [title, setTitle] = useState("Tomorrow's Fresh Menu"); const [cutoff, setCutoff] = useState("Order before 9:00 PM for next-day delivery"); const [query, setQuery] = useState("");
  useEffect(() => { Promise.all([window.admin.menu.catalog(), window.admin.menu.getCurrent()]).then(([value, current]) => { setCatalog(value); if (current) { setDate(current.date); setTitle(current.title); setCutoff(current.orderCutoff); setSelected(current.itemIds); setFeatured(current.featuredItemId); } }); }, []);
  const items = catalog.items.filter((item: any) => item.available && item.name.toLowerCase().includes(query.toLowerCase()));
  async function publish() { const incompatible = selected.filter((id) => !catalog.items.find((item: any) => item.id === id)?.webCompatible); if (incompatible.length) throw new Error("Remove items that are not compatible with the website catalog."); const payload: Publication = { date, published: true, title, itemIds: selected, featuredItemId: featured, orderCutoff: cutoff }; await window.admin.menu.publish(payload); notify("Menu saved locally. Use Sync Centre to push it to Neon."); }
  return <section className="menu-builder"><div><Panel title="Build the one-day menu"><div className="publish-fields"><label>Service date<input type="date" value={date} onChange={(event) => setDate(event.target.value)} /></label><label>Title<input value={title} onChange={(event) => setTitle(event.target.value)} /></label><label>Cutoff<input value={cutoff} onChange={(event) => setCutoff(event.target.value)} /></label></div><input className="search" placeholder="Search the master menu" value={query} onChange={(event) => setQuery(event.target.value)} /><div className="catalog-grid">{items.map((item: any) => <label className={selected.includes(item.id) ? "selected" : ""} key={item.id}><input type="checkbox" checked={selected.includes(item.id)} onChange={() => setSelected((current) => current.includes(item.id) ? current.filter((id) => id !== item.id) : [...current, item.id])} /><span><strong>{item.name}</strong><small>{item.portion} / {money(item.price)}</small></span></label>)}</div></Panel></div>
    <aside className="selection-card"><span>{selected.length} selected</span><h2>Tomorrow's menu</h2>{selected.map((id) => { const item = catalog.items.find((value: any) => value.id === id); return <div className="selected-line" key={id}><button className={featured === id ? "star on" : "star"} onClick={() => setFeatured(featured === id ? null : id)}>*</button><span>{item?.name}</span><b>{money(item?.price)}</b></div>; })}<button className="primary publish" disabled={!selected.length} onClick={() => publish().catch((error) => notify(error.message))}>Save menu locally</button><small>* marks the featured dish. Push the queued publication from Sync Centre.</small></aside>
  </section>;
}

function CloudOrdersPage({ notify }: { notify: (message: string) => void }) {
  const [rows, setRows] = useState<any[]>([]); const [query, setQuery] = useState(""); const [detail, setDetail] = useState<any>(null);
  const load = () => window.admin.cloudOrders.list(query).then(setRows); useEffect(() => { load(); }, [query]);
  async function select(id: string) { setDetail(await window.admin.cloudOrders.detail(id)); }
  async function status(id: string, value: any) { await window.admin.cloudOrders.updateStatus(id, value); await load(); notify("Cloud order status saved locally and queued for sync."); }
  return <section className="split wide-left"><Panel title="Orders"><p className="muted">Neon is the primary order source. The latest successful pull remains available offline in SQLite.</p><input className="search" placeholder="Search order, customer or phone" value={query} onChange={(event) => setQuery(event.target.value)} /><div className="order-list">{rows.map((row) => <article key={row.id}><div><strong>{row.customer_name || row.customer_phone || row.id}</strong><span>{row.order_number || row.id} / {row.service_date}</span></div><b>{money(row.total)}</b><select value={row.status} onChange={(event) => status(row.id, event.target.value)}>{["handoff_created", "customer_confirmed_sent", "confirmed", "preparing", "ready", "completed", "cancelled"].map((value) => <option key={value}>{value}</option>)}</select><button onClick={() => select(row.id)}>View</button></article>)}</div></Panel><Panel title="Order detail">{detail ? <div className="detail-card"><b>{detail.order_number || detail.id}</b><span>{detail.customer_name} / {detail.customer_phone}</span><span>{detail.fulfilment} / {detail.service_date}</span>{detail.address&&<span>{detail.address}</span>}<div className="order-detail-lines">{detail.lines?.map((line: any) => <article key={line.id}><div><strong>{line.name}</strong>{line.portion&&<small>{line.portion}</small>}<span>{line.quantity} x {money(line.unit_price)} each</span>{line.bundle_selection?.map((selection:any)=><small key={selection.group}>{selection.group}: {selection.choices?.map((choice:any)=>choice.name).join(", ")}</small>)}</div><b>{money(line.line_total)}</b></article>)}</div><footer><span>Order total</span><strong>{money(detail.total)}</strong></footer></div> : <Empty text="Select an order to inspect it." />}</Panel></section>;
}

const blankCatalogItem = (categoryId = ""): CatalogItem => ({ id: "", categoryId, type: "dish", name: "", description: "", portion: "1 serving", price: 0, image: undefined, available: true, isNew: false, tags: [], order: 0, archived: false, webCompatible: true, bundleGroups: [] });
const catalogImage = (image?: string | null) => `./catalog/${encodeURIComponent(image || "food-placeholder.jpeg")}`;
function CatalogPage({ notify }: { notify: (message: string) => void }) {
  const [catalog,setCatalog]=useState<{categories:CatalogCategory[];items:CatalogItem[]}>({categories:[],items:[]}); const [query,setQuery]=useState(""); const [editing,setEditing]=useState<CatalogItem|null>(null); const [type,setType]=useState("all"); const [status,setStatus]=useState("active"); const [preview,setPreview]=useState(false); const [quick,setQuick]=useState<string|null>(null); const [exporting,setExporting]=useState(false); const [managingCategories,setManagingCategories]=useState(false);
  const load=()=>window.admin.catalog.get().then(setCatalog); useEffect(()=>{load();},[]);
  const visibleCategories=catalog.categories.filter((category)=>category.active);
  const rows=catalog.items.filter((item)=>(status==="all"||(status==="active"?!item.archived:item.archived))&&(type==="all"||item.type===type)&&searchableCatalogItem(item,query));
  function edit(item:CatalogItem){setEditing({...item,tags:[...item.tags],bundleGroups:item.bundleGroups.map((group)=>({...group,choices:group.choices.map((choice)=>({...choice}))}))});}
  async function save(item:CatalogItem){await window.admin.catalog.save(item);await load();setEditing(null);notify(`${item.name} was saved locally. Push from Sync Centre to update Neon.`);}
  async function exportPdf(){setExporting(true);try{const result=await window.admin.catalog.exportPdf();if(result.canceled){notify("Menu PDF export was cancelled.");return;}notify(result.warning??`Menu PDF saved successfully (${result.pageCount} pages).`);}catch(error){notify(`Menu PDF export failed: ${error instanceof Error?error.message:String(error)}`);}finally{setExporting(false);}}
  async function saveCategory(category:CatalogCategory){await window.admin.catalog.saveCategory(category);await load();notify(`${category.name} was saved locally.`);}
  async function toggleCategory(category:CatalogCategory){if(category.active&&!confirm(`Remove ${category.name} from the master menu? Its items will remain stored.`))return;await window.admin.catalog.setCategoryActive(category.id,!category.active);await load();notify(`${category.name} was ${category.active?"removed from":"restored to"} the master menu.`);}
  return <><section className="visual-catalog-page"><div className="catalog-toolbar"><div className="catalog-heading"><div><small>{preview?"PREVIEW MODE":"EDIT MODE"}</small><h2>Menu card editor</h2></div><button className="pdf-export" disabled={exporting} onClick={exportPdf}>{exporting?"Generating PDF...":"Export menu PDF"}</button></div><div className="toolbar-actions"><button className="primary" disabled={!visibleCategories.length} onClick={()=>edit(blankCatalogItem(visibleCategories[0]?.id))}>+ Add catalog item</button><button onClick={()=>setManagingCategories(true)}>Manage categories</button><button onClick={()=>setPreview(!preview)}>{preview?"Return to edit":"Preview catalog"}</button></div><label>Search<input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Search ID, name, portion, description or tags"/></label><label>Type<select value={type} onChange={(event)=>setType(event.target.value)}><option value="all">All types</option><option value="dish">Dish</option><option value="combo">Combo</option><option value="thali">Thali</option></select></label><label>Status<select value={status} onChange={(event)=>setStatus(event.target.value)}><option value="active">Active</option><option value="archived">Archived</option><option value="all">All</option></select></label></div><div className="category-admin-grid">{visibleCategories.map((category)=>{const categoryItems=rows.filter((item)=>item.categoryId===category.id);if(preview&&!categoryItems.length)return null;return <section className="category-panel" key={category.id}><header><div><small>{String(category.order).padStart(2,"0")}</small><h2>{category.name}</h2></div>{!preview&&<button onClick={()=>edit(blankCatalogItem(category.id))}>+ Add</button>}</header><div>{categoryItems.length===0&&<Empty text="No matching items."/>}{categoryItems.map((item)=><article className={item.archived?"archived":""} key={item.id}><img src={catalogImage(item.image)} onError={(event)=>{event.currentTarget.src=catalogImage();}}/><div className="catalog-card-copy">{quick===item.id?<QuickCatalogEdit item={item} cancel={()=>setQuick(null)} saved={async(next)=>{await window.admin.catalog.save(next);setQuick(null);load();notify(`${next.name} was updated.`);}}/>:<><div className="catalog-title"><h3>{item.name}</h3><strong>{money(item.price)}</strong></div><p>{item.portion||item.description}</p><div className="badges"><span>{item.type}</span>{item.isNew&&<span>New</span>}{!item.available&&<span>Unavailable</span>}{!item.webCompatible&&<span>Desktop only</span>}{item.archived&&<span>Archived</span>}</div>{!preview&&<footer>{!item.archived&&<><button onClick={()=>setQuick(item.id)}>Quick edit</button><button onClick={()=>edit(item)}>Edit details</button><button onClick={()=>window.admin.catalog.save({...item,webCompatible:!item.webCompatible}).then(load)}>{item.webCompatible?"Make desktop only":"Enable on website"}</button><button className="danger" onClick={async()=>{if(!confirm(`Archive ${item.name}?`))return;await window.admin.catalog.archive(item.id,true);load();}}>Archive</button></>}{item.archived&&<button onClick={async()=>{await window.admin.catalog.archive(item.id,false);load();}}>Restore</button>}</footer>}</>}</div></article>)}</div></section>;})}</div></section>{editing&&<CatalogEditorModal item={editing} categories={catalog.categories} items={catalog.items} onClose={()=>setEditing(null)} onSave={save} notify={notify}/>} {managingCategories&&<CategoryManagerModal categories={catalog.categories} onClose={()=>setManagingCategories(false)} onSave={saveCategory} onToggle={toggleCategory}/>}</>;
}

function LegacyCatalogPage({ notify }: { notify: (message: string) => void }) {
  const [catalog, setCatalog] = useState<{ categories: any[]; items: CatalogItem[] }>({ categories: [], items: [] }); const [query, setQuery] = useState(""); const [editing, setEditing] = useState<CatalogItem | null>(null); const [type, setType] = useState("all"); const [status, setStatus] = useState("active"); const [preview, setPreview] = useState(false); const [quick, setQuick] = useState<string | null>(null); const [exporting, setExporting] = useState(false);
  const load = () => window.admin.catalog.get().then(setCatalog); useEffect(() => { load(); }, []);
  const rows = catalog.items.filter((item) => (status==="all"||(status==="active"?!item.archived:item.archived))&&(type==="all"||item.type===type)&&(item.name+" "+item.portion).toLowerCase().includes(query.toLowerCase()));
  function edit(item: CatalogItem) { setEditing({ ...item, tags: [...item.tags], bundleGroups: item.bundleGroups.map((group)=>({...group,choices:group.choices.map((choice)=>({...choice}))})) }); }
  async function save(item: CatalogItem) { await window.admin.catalog.save(item); await load(); setEditing(null); notify(`${item.name} was saved locally. Push from Sync Centre to update Neon.`); }
  async function exportPdf() { setExporting(true); try { const result = await window.admin.catalog.exportPdf(); if (result.canceled) { notify("Menu PDF export was cancelled."); return; } notify(result.warning ?? `Menu PDF saved successfully (${result.pageCount} pages).`); } catch (error) { notify(`Menu PDF export failed: ${error instanceof Error ? error.message : String(error)}`); } finally { setExporting(false); } }
  return <><section className="visual-catalog-page"><div className="catalog-toolbar"><div className="catalog-heading"><div><small>{preview?"PREVIEW MODE":"EDIT MODE"}</small><h2>Menu card editor</h2></div><button className="pdf-export" disabled={exporting} onClick={exportPdf}>{exporting?"Generating PDF...":"Export menu PDF"}</button></div>
<div className="toolbar-actions"><button className="primary" onClick={()=>edit(blankCatalogItem(catalog.categories[0]?.id))}>+ Add catalog item</button><button onClick={()=>setPreview(!preview)}>{preview?"Return to edit":"Preview catalog"}</button></div>
<label>Search<input value={query} onChange={(event)=>setQuery(event.target.value)} placeholder="Search name or portion"/></label><label>Type<select value={type} onChange={(event)=>setType(event.target.value)}><option value="all">All types</option><option value="dish">Dish</option><option value="combo">Combo</option><option value="thali">Thali</option></select></label><label>Status<select value={status} onChange={(event)=>setStatus(event.target.value)}><option value="active">Active</option><option value="archived">Archived</option><option value="all">All</option></select></label></div><div className="category-admin-grid">{catalog.categories.map((category)=>{const categoryItems=rows.filter((item)=>item.categoryId===category.id);if(preview&&!categoryItems.length)return null;return <section className="category-panel" key={category.id}><header><div><small>{String(category.order).padStart(2,"0")}</small><h2>{category.name}</h2></div>{!preview&&<button onClick={()=>edit(blankCatalogItem(category.id))}>+ Add</button>}</header><div>{categoryItems.length===0&&<Empty text="No matching items."/>}{categoryItems.map((item)=><article className={item.archived?"archived":""} key={item.id}><img src={catalogImage(item.image)} onError={(event)=>{event.currentTarget.src=catalogImage();}}/><div className="catalog-card-copy">{quick===item.id?<QuickCatalogEdit item={item} cancel={()=>setQuick(null)} saved={async(next)=>{await window.admin.catalog.save(next);setQuick(null);load();notify(`${next.name} was updated.`);}}/>:<><div className="catalog-title"><h3>{item.name}</h3><strong>{money(item.price)}</strong></div><p>{item.portion||item.description}</p><div className="badges"><span>{item.type}</span>{item.isNew&&<span>New</span>}{!item.available&&<span>Unavailable</span>}{item.archived&&<span>Archived</span>}</div>{!preview&&<footer>{!item.archived&&<><button onClick={()=>setQuick(item.id)}>Quick edit</button><button onClick={()=>edit(item)}>Edit details</button><button className="danger" onClick={async()=>{if(!confirm(`Archive ${item.name}?`))return;await window.admin.catalog.archive(item.id,true);load();}}>Archive</button></>}{item.archived&&<button onClick={async()=>{await window.admin.catalog.archive(item.id,false);load();}}>Restore</button>}</footer>}</>}</div></article>)}</div></section>;})}</div></section>{editing&&<CatalogEditorModal item={editing} categories={catalog.categories} items={catalog.items} onClose={()=>setEditing(null)} onSave={save} notify={notify}/>}</>;
}

function QuickCatalogEdit({item,cancel,saved}:{item:CatalogItem;cancel():void;saved(item:CatalogItem):Promise<void>}){const [name,setName]=useState(item.name);const [price,setPrice]=useState(item.price);return <div className="quick-edit"><label>Name<input value={name} onChange={(event)=>setName(event.target.value)}/></label><label>Price<input type="number" min="0" value={price} onChange={(event)=>setPrice(Number(event.target.value))}/></label><div><button onClick={()=>saved({...item,name,price})}>Save</button><button onClick={cancel}>Cancel</button></div></div>}

function OperationsPage({ notify }: { notify: (message: string) => void }) {
  const [config, setConfig] = useState<RuntimeConfig | null>(null);
  useEffect(() => { window.admin.operations.get().then(setConfig); }, []);
  if (!config) return <Empty text="Loading operations settings..." />;
  const site = (key: keyof RuntimeConfig["site"], value: string) => setConfig({ ...config, site: { ...config.site, [key]: value } });
  const operation = (key: keyof RuntimeConfig["operations"], value: boolean | string) => setConfig({ ...config, operations: { ...config.operations, [key]: value } });
  const area = (key: keyof RuntimeConfig["serviceArea"], value: any) => setConfig({ ...config, serviceArea: { ...config.serviceArea, [key]: value } });
  const location = (values: Partial<RuntimeConfig["publicLocation"]>) => setConfig({ ...config, publicLocation: { ...config.publicLocation, ...values } });
  const updatePlatform = (index:number, values:Partial<RuntimeConfig["orderingPlatforms"][number]>) => { const next=[...config.orderingPlatforms];next[index]={...next[index],...values};setConfig({...config,orderingPlatforms:next}); };
  const addPlatform = () => { const id=`platform-${crypto.randomUUID()}`;setConfig({...config,orderingPlatforms:[...config.orderingPlatforms,{id,name:"New platform",description:"",url:"",status:"coming-soon",order:config.orderingPlatforms.length+1}]}); };
  async function save() { if (!config) return; await window.admin.operations.save(config); notify("Operations settings saved. Push from Sync Centre to update Neon."); }
  return <div className="operations-page"><h2>Run the kitchen from one place.</h2><div className="operations-form"><Panel title="Operating status"><div className="toggle-grid"><label><input type="checkbox" checked={config.operations.open} onChange={(event)=>operation("open",event.target.checked)}/>Accepting pre-orders</label><label><input type="checkbox" checked={config.operations.pickupEnabled} onChange={(event)=>operation("pickupEnabled",event.target.checked)}/>Pickup enabled</label><label><input type="checkbox" checked={config.operations.deliveryEnabled} onChange={(event)=>operation("deliveryEnabled",event.target.checked)}/>Delivery enabled</label></div><label>Status message<textarea rows={3} value={config.operations.message} onChange={(event)=>operation("message",event.target.value)}/></label></Panel><Panel title="Contact and site"><div className="form-grid"><label>Brand name<input value={config.site.brandName} onChange={(event)=>site("brandName",event.target.value)}/></label><label>Tagline<input value={config.site.tagline} onChange={(event)=>site("tagline",event.target.value)}/></label><label>Mobile<input value={config.site.mobile} onChange={(event)=>site("mobile",event.target.value.replace(/\D/g,"").slice(0,10))}/><small>10 digits without +91.</small></label><label>Order cutoff<input value={config.site.orderCutoff} onChange={(event)=>site("orderCutoff",event.target.value)}/></label></div></Panel><Panel title="Service area"><div className="form-grid"><label>Pickup cities<input value={config.serviceArea.pickupCities.join(", ")} onChange={(event)=>area("pickupCities",event.target.value.split(",").map((value)=>value.trim()).filter(Boolean))}/></label><label>Pickup state<input value={config.serviceArea.pickupState} onChange={(event)=>area("pickupState",event.target.value)}/></label><label>Country<input value={config.serviceArea.pickupCountry} onChange={(event)=>area("pickupCountry",event.target.value)}/></label><label>Kitchen Place ID<input value={config.serviceArea.kitchenPlaceId} onChange={(event)=>area("kitchenPlaceId",event.target.value)}/></label><label>Kitchen latitude<input type="number" step="any" value={config.serviceArea.kitchenLatitude??""} onChange={(event)=>area("kitchenLatitude",event.target.value?Number(event.target.value):null)}/></label><label>Kitchen longitude<input type="number" step="any" value={config.serviceArea.kitchenLongitude??""} onChange={(event)=>area("kitchenLongitude",event.target.value?Number(event.target.value):null)}/></label><label>Delivery radius (km)<input type="number" min="0.1" step="0.1" value={config.serviceArea.deliveryRadiusKm} onChange={(event)=>area("deliveryRadiusKm",Number(event.target.value))}/></label></div></Panel></div><Panel title="Ordering platforms" action={<button onClick={addPlatform}>+ Add platform</button>}><div className="platform-admin-list">{config.orderingPlatforms.slice().sort((a,b)=>a.order-b.order).map((platform)=>{const index=config.orderingPlatforms.findIndex((entry)=>entry.id===platform.id);return <article key={platform.id}><div className="platform-fields"><label>Platform name<input value={platform.name} onChange={(event)=>updatePlatform(index,{name:event.target.value})}/></label><label>Status<select value={platform.status} onChange={(event)=>updatePlatform(index,{status:event.target.value as any})}><option value="available">Available</option><option value="coming-soon">Coming soon</option><option value="hidden">Hidden</option></select></label><label>Description<input value={platform.description} onChange={(event)=>updatePlatform(index,{description:event.target.value})}/></label><label>Storefront URL<input value={platform.url} onChange={(event)=>updatePlatform(index,{url:event.target.value})}/></label><label>Display order<input type="number" min="1" value={platform.order} onChange={(event)=>updatePlatform(index,{order:Number(event.target.value)})}/></label><button className="danger" onClick={()=>setConfig({...config,orderingPlatforms:config.orderingPlatforms.filter((entry)=>entry.id!==platform.id)})}>Remove</button></div><div className="platform-preview"><small>{platform.status.replace("-"," ")}</small><h3>{platform.name||"Platform name"}</h3><p>{platform.description||"Platform description"}</p></div></article>;})}</div></Panel><Panel title="Public kitchen location"><div className="location-editor"><div className="stack-form"><label className="check"><input type="checkbox" checked={config.publicLocation.enabled} onChange={(event)=>location({enabled:event.target.checked})}/>Show publicly</label><label>Location name<input value={config.publicLocation.name} onChange={(event)=>location({name:event.target.value})}/></label><label>Public address<textarea rows={3} value={config.publicLocation.address} onChange={(event)=>{const address=event.target.value;location({address,mapQuery:address,googleMapsUrl:`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`});}}/></label><label>Directions or landmark<textarea rows={3} value={config.publicLocation.directions} onChange={(event)=>location({directions:event.target.value})}/></label><label>Google Maps link<input value={config.publicLocation.googleMapsUrl} onChange={(event)=>location({googleMapsUrl:event.target.value})}/></label></div><div className="location-preview"><small>PUBLIC LOCATION PREVIEW</small><h3>{config.publicLocation.name||"Kitchen location"}</h3><p>{config.publicLocation.address||"Enter the public address."}</p><p>{config.publicLocation.directions}</p>{config.publicLocation.googleMapsUrl&&<a href={config.publicLocation.googleMapsUrl} target="_blank" rel="noreferrer">Verify in Google Maps</a>}</div></div></Panel><button className="primary save-operations" onClick={()=>save().catch((error)=>notify(error.message))}>Save operations</button></div>;
}

function PreviewCard({ value }: { value: SyncPreview | PushPreview | null }) {
  if (!value) return <div className="preview-card"><span>Run preview before syncing.</span></div>;
  const push = "pushableDirty" in value ? value : null;
  return <div className="preview-card">{push ? <><div className="push-counts"><b>{push.pushableDirty}<small>Pushable</small></b><b>{push.excludedDirty}<small>Local-only / excluded</small></b></div><div className="push-sections"><span>Orders <b>{push.sections.orders}</b></span><span>Catalog <b>{push.sections.catalog}</b></span><span>One-day menu <b>{push.sections.menu}</b></span><span>Operations <b>{push.sections.operations}</b></span></div><span>{push.conflicts} conflicts in pushable records</span></> : <><span>{value.inserts} inserts / {value.updates} updates</span><span>{value.conflicts} conflicts / {value.dirty} dirty</span></>}<small>{value.entities.slice(0, 20).map((entry) => entry.action + ": " + entry.type + "/" + entry.id).join("\n") || "No changes"}</small></div>;
}
function SyncPage({ notify }: { notify: (message: string) => void }) {
  const [status, setStatus] = useState<SyncStatus | null>(null); const [pull, setPull] = useState<SyncPreview | null>(null); const [push, setPush] = useState<PushPreview | null>(null); const [conflicts, setConflicts] = useState<any[]>([]); const [history, setHistory] = useState<any[]>([]); const [busy, setBusy] = useState(false);
  const load = async () => { const [nextStatus, nextConflicts, nextHistory] = await Promise.all([window.admin.sync.status(), window.admin.sync.conflicts(), window.admin.sync.history()]); setStatus(nextStatus); setConflicts(nextConflicts); setHistory(nextHistory); if(nextStatus.connection.error)notify(`Environment configuration error: ${nextStatus.connection.error}`); };
  useEffect(() => { load().catch((error) => notify(error.message)); }, []);
  async function run(kind: "pull" | "push") { setBusy(true); try { if (kind === "pull") setPull(await window.admin.sync.pull()); else setPush(await window.admin.sync.push()); await load(); notify((kind === "pull" ? "Pull" : "Push") + " completed."); } finally { setBusy(false); } }
  return <><section className="metric-grid"><Metric label="Connection" value={status?.online ? "Online" : "Offline"} tone={status?.online ? "green" : "red"} /><Metric label="Dirty records" value={String(status?.dirty ?? 0)} tone="gold" /><Metric label="Open conflicts" value={String(status?.conflicts ?? 0)} tone="red" /></section><section className="sync-grid"><Panel title="Pull Neon to SQLite" action={<button disabled={busy} onClick={async () => setPull(await window.admin.sync.previewPull())}>Preview</button>}><PreviewCard value={pull} /><button className="primary" disabled={busy || !pull} onClick={() => run("pull").catch((error) => notify(error.message))}>Pull from Neon</button></Panel><Panel title="Push SQLite to Neon" action={<button disabled={busy} onClick={async () => setPush(await window.admin.sync.previewPush())}>Preview</button>}><PreviewCard value={push} /><button className="primary" disabled={busy || !push || push.pushableDirty === 0 || push.conflicts > 0} onClick={() => run("push").catch((error) => notify(error.message))}>Push to Neon</button></Panel></section><section className="split"><Panel title="Conflict review">{conflicts.length ? <div className="conflict-list">{conflicts.map((row) => <article key={row.id}><b>{row.entity_type} / {row.entity_id}</b><span>Both SQLite and Neon changed this record.</span><div><button onClick={async () => { await window.admin.sync.resolve(row.id, "local"); load(); }}>Keep SQLite</button><button onClick={async () => { await window.admin.sync.resolve(row.id, "neon"); load(); }}>Use Neon</button></div></article>)}</div> : <Empty text="No unresolved conflicts." />}</Panel><Panel title="Sync audit history"><DataTable rows={history} columns={[["started_at", "Started"], ["direction", "Direction"], ["status", "Status"], ["summary", "Summary"]]} /></Panel></section></>;
}

function InboxPage({ notify }: { notify: (message: string) => void }) {
  const [rows, setRows] = useState<any[]>([]); const load = () => window.admin.inbox.list().then(setRows); useEffect(() => { load(); }, []);
  return <Panel title="WhatsApp Business inbox" action={<button className="primary" onClick={async () => { const result = await window.admin.inbox.sync(); load(); notify(`${result.imported} structured orders, ${result.unmatched} unmatched messages synced.`); }}>Sync inbox</button>}><DataTable rows={rows} columns={[["received_at", "Received"], ["sender", "Sender"], ["status", "Status"], ["message", "Message"]]} /></Panel>;
}

function SettingsPage({ notify }: { notify: (message: string) => void }) {
  const [form, setForm] = useState<any>({ webhookUrl: "", neonDatabaseUrl: "", inboxToken: "" }); const [update, setUpdate] = useState("");
  useEffect(() => { window.admin.settings.get().then((value) => setForm((current: any) => ({ ...current, ...value }))); return window.admin.updates.onStatus(setUpdate); }, []);
  async function save(event: React.FormEvent) { event.preventDefault(); await window.admin.settings.set({ webhookUrl: form.webhookUrl }, { neonDatabaseUrl: form.neonDatabaseUrl, inboxToken: form.inboxToken }); const updated=await window.admin.settings.get(); setForm({ ...updated, neonDatabaseUrl: "", inboxToken: "" }); notify("Settings saved securely and are active."); }
  return <section className="settings-grid"><Panel title="Connections"><form className="stack-form" onSubmit={save}><div className={form.hasNeonUrl ? "connection-ok" : "connection-warn"}>{form.hasNeonUrl ? "Neon database configured" : "Neon database not configured"}</div><label>Webhook URL<input value={form.webhookUrl ?? ""} onChange={(event) => setForm({ ...form, webhookUrl: event.target.value })} /></label><label>Neon database URL<input type="password" placeholder={form.hasNeonUrl ? "Saved securely - enter to replace" : "postgresql://..."} value={form.neonDatabaseUrl ?? ""} onChange={(event) => setForm({ ...form, neonDatabaseUrl: event.target.value })} /></label><label>Inbox API token<input type="password" placeholder={form.hasInboxToken ? "Saved securely - enter to replace" : "Token"} value={form.inboxToken ?? ""} onChange={(event) => setForm({ ...form, inboxToken: event.target.value })} /></label><button className="primary">Save settings</button></form></Panel><Panel title="Data safety"><div className="action-list"><button onClick={async () => { if (await window.admin.settings.backup()) notify("Encrypted backup saved."); }}>Create encrypted backup</button><button onClick={async () => { if (await window.admin.settings.restore()) notify("Backup staged. Restart to complete restore."); }}>Restore a backup</button></div></Panel><Panel title="Application updates"><p className="muted">{update || "Updates are delivered through signed GitHub Releases."}</p><button className="primary" onClick={() => window.admin.updates.check()}>Check for updates</button>{update === "update-downloaded" && <button onClick={() => window.admin.updates.install()}>Restart and install</button>}</Panel></section>;
}

function Panel({ title, action, children }: { title: string; action?: React.ReactNode; children: React.ReactNode }) { return <section className="panel"><div className="panel-head"><h2>{title}</h2>{action}</div>{children}</section>; }
function Empty({ text }: { text: string }) { return <div className="empty">{text}</div>; }
function DataTable({ rows, columns, moneyKeys = [], actions }: { rows: any[]; columns: [string, string][]; moneyKeys?: string[]; actions?: (row: any) => React.ReactNode }) { if (!rows.length) return <Empty text="No records found for this period." />; return <div className="table-wrap"><table><thead><tr>{columns.map(([, label]) => <th key={label}>{label}</th>)}{actions && <th>Actions</th>}</tr></thead><tbody>{rows.map((row, index) => <tr key={row.id ?? index}>{columns.map(([key]) => <td key={key}>{moneyKeys.includes(key) ? money(row[key]) : displayValue(key,row[key])}</td>)}{actions && <td>{actions(row)}</td>}</tr>)}</tbody></table></div>; }

createRoot(document.getElementById("root")!).render(<React.StrictMode><App /></React.StrictMode>);
